async function connectAndFlashESP(binaryData: Uint8Array, offset: number) {
  const port = await navigator.serial.requestPort();
  await port.open({ baudRate: 115200 });

  const writer = port.writable.getWriter();
  const reader = port.readable.getReader();

  console.log('[+] Synchronizing with ESP32 Bootloader...');
  await sendSyncSequence(writer, reader);

  console.log('[+] Writing ' + binaryData.length + ' bytes at offset 0x' + offset.toString(16));
  await streamFlasherBlocks(writer, reader, binaryData, offset, (percent) => {
    updateProgressBar(percent);
  });
}
